func color(_ hex: Int) -> CGColor {
    CGColor(red: CGFloat(hex >> 16 & 255)/255, green: CGFloat(hex >> 8 & 255)/255,
            blue: CGFloat(hex & 255)/255, alpha: 1)
}

final class Sheet {
    let ctx: CGContext
    init(_ path: String, _ title: String) {
        var box = CGRect(x: 0, y: 0, width: width, height: height)
        ctx = CGContext(URL(fileURLWithPath: path) as CFURL, mediaBox: &box,
                        [kCGPDFContextTitle as String: title] as CFDictionary)"'!
    }
    func page(_ draw: () -> Void) {
        ctx.beginPDFPage(nil)
        draw()
        ctx.endPDFPage()
    }
    func finish() { ctx.closePDF() }
    func p(_ x: CGFloat, _ y: CGFloat) -> CGPoint { CGPoint(x: x, y: height - y) }
    func box(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat,
             fill: CGColor? = nil, border: CGColor? = nil, radius: CGFloat = 0, weight: CGFloat = 0.8) {
        ctx.addPath(CGPath(roundedRect: CGRect(x: x, y: height-y-h, width: w, height: h),
                           cornerWidth: radius, cornerHeight: radius, transform: nil))
        if let fill { ctx.setFillColor(fill) }
        if let border { ctx.setStrokeColor(border); ctx.setLineWidth(weight) }
        ctx.drawPath(using: fill == nil ? .stroke : (border == nil ? .fill : .fillStroke))
    }
    func rule(_ x: CGFloat, _ y: CGFloat, _ end: CGFloat, _ stroke: CGColor = line,
              weight: CGFloat = 0.75, dash: [CGFloat] = []) {
        ctx.saveGState()
        ctx.setStrokeColor(stroke)
        ctx.setLineWidth(weight)
        ctx.setLineDash(phase: 0, lengths: dash)
        ctx.move(to: p(x,y))
        ctx.addLine(to: p(end,y))
        ctx.strokePath()
        ctx.restoreGState()
    }
    func stroke(_ shade: CGColor, _ weight: CGFloat, _ draw: (CGMutablePath) -> Void) {
        let path = CGMutablePath()
        draw(path)
        ctx.addPath(path)
        ctx.setStrokeColor(shade)
        ctx.setLineWidth(weight)
        ctx.setLineCap(.round)
        ctx.setLineJoin(.round)
        ctx.strokePath()
    }
    @discardableResult
    func text(_ value: String, _ x: CGFloat, _ baseline: CGFloat, _ size: CGFloat,
              _ face: String = sans, _ shade: CGColor = ink, tracking: CGFloat = 0,
              right: CGFloat = 570) -> CGFloat {
        let font = CTFontCreateWithName(face as CFString, size, nil)
        precondition((CTFontCopyPostScriptName(font) as String) == face, "Missing font: '"\\(face)\")
        let attributes: [NSAttributedString.Key: Any] = [
            .font: font, .foregroundColor: shade, .kern: tracking
        ]
        let content = NSAttributedString(string: value, attributes: attributes)
        let shaped = CTLineCreateWithAttributedString(content)
        let textWidth = CGFloat(CTLineGetTypographicBounds(shaped, nil, nil, nil))
        precondition(x + textWidth <= right + 0.1, \"Line overflow: \\(value) [\\(x+textWidth) > \\(right)]\")
        ctx.textMatrix = .identity
        ctx.textPosition = p(x, baseline)
        CTLineDraw(shaped, ctx)
        return textWidth
    }
    func lines(_ values: [String], _ x: CGFloat, _ y: CGFloat, _ size: CGFloat,
               lead: CGFloat, _ face: String = sans, _ shade: CGColor = ink, right: CGFloat = 570) {
        for (i, value) in values.enumerated() {
            text(value, x, y + CGFloat(i)*lead, size, face, shade, right: right)
        }
    }
    func label(_ value: String, _ x: CGFloat, _ y: CGFloat, _ shade: CGColor = plum) {
        text(value, x, y, 9.5, semibold, shade, tracking: 1.35)
    }
    func imprint(_ x: CGFloat, _ y: CGFloat, _ scale: CGFloat = 1) {
        func a(_ i: CGFloat, _ j: CGFloat) -> CGPoint { p(x+i*scale,y+j*scale) }
        stroke(olive, 2.1*scale) { path in
            path.move(to: a(5,96))
            path.addQuadCurve(to: a(73,101), control: a(42,83))
            path.addQuadCurve(to: a(141,96), control: a(104,83))
            path.addLine(to: a(148,129))
            path.addQuadCurve(to: a(73,137), control: a(105,120))
            path.addQuadCurve(to: a(-2,129), control: a(41,120))
            path.closeSubpath()
            path.move(to: a(73,102)); path.addLine(to: a(73,136))
            path.move(to: a(14,108)); path.addQuadCurve(to: a(61,111), control: a(37,102))
            path.move(to: a(11,118)); path.addQuadCurve(to: a(61,121), control: a(38,112))
            path.move(to: a(86,111)); path.addQuadCurve(to: a(131,108), control: a(111,102))
            path.move(to: a(86,121)); path.addQuadCurve(to: a(134,118), control: a(112,112))
        }
        stroke(plum, 2.2*scale) { path in
            path.move(to: a(44,43)); path.addLine(to: a(101,43))
            path.addCurve(to: a(74,83), control1: a(100,70), control2: a(91,83))
            path.addCurve(to: a(44,43), control1: a(56,83), control2: a(45,71))
            path.closeSubpath()
            path.move(to: a(101,49))
            path.addCurve(to: a(98,69), control1: a(124,44), control2: a(124,68))
            path.move(to: a(39,85)); path.addQuadCurve(to: a(106,85), control: a(73,93))
            path.move(to: a(65,34)); path.addCurve(to: a(65,12), control1: a(77,26), control2: a(57,20))
            path.move(to: a(81,34)); path.addCurve(to: a(83,3), control1: a(96,23), control2: a(72,18))
        }
    }
    func pageHead(_ kicker: String, _ title: String, _ sub: String) {
        rule(42, 44, 570, olive, weight: 1.2)
        label(kicker, 42, 66)
        text(title, 42, 112, 36, serif)
        text(sub, 43, 138, 12, sans, muted)
    }
    func foot(_ wording: String, _ page: String) {
        rule(42, 735, 570)
        label(wording, 42, 753, olive)
        label(page, 542, 753, olive)
    }
}

